export function localPoint(rect, clientX, clientY) {
    return {
        x: rect.width ? clamp01((clientX - rect.left) / rect.width) : 0.5,
        y: rect.height ? clamp01((clientY - rect.top) / rect.height) : 0.5,
    };
}
export function signedPoint(rect, clientX, clientY) {
    const halfW = rect.width / 2;
    const halfH = rect.height / 2;
    return {
        x: halfW ? (clientX - (rect.left + halfW)) / halfW : 0,
        y: halfH ? (clientY - (rect.top + halfH)) / halfH : 0,
    };
}
export function edgeFromPoint(rect, clientX, clientY) {
    const { x, y } = signedPoint(rect, clientX, clientY);
    if (Math.abs(x) > Math.abs(y))
        return x > 0 ? 'right' : 'left';
    return y > 0 ? 'bottom' : 'top';
}
export function edgeVector(edge) {
    switch (edge) {
        case 'top':
            return { x: 0, y: 1 };
        case 'bottom':
            return { x: 0, y: -1 };
        case 'left':
            return { x: 1, y: 0 };
        case 'right':
            return { x: -1, y: 0 };
    }
}
export function angleOf(vec) {
    const deg = (Math.atan2(vec.y, vec.x) * 180) / Math.PI;
    return deg < 0 ? deg + 360 : deg;
}
export function normalize(vec) {
    const length = Math.hypot(vec.x, vec.y);
    if (!length)
        return { x: 0, y: 0 };
    return { x: vec.x / length, y: vec.y / length };
}
export function clamp01(n) {
    return n < 0 ? 0 : n > 1 ? 1 : n;
}
export function clamp(n, lo, hi) {
    return Math.min(hi, Math.max(lo, n));
}
export function round(n, places = 4) {
    const factor = 10 ** places;
    return Math.round(n * factor) / factor;
}
